(function () {
    'use strict';

    /**
     * @ngdoc
     * @description
     * Select event defined within a page. Event may generated by button, timer, select, etc.
     * ```html
     * <udp-page-event-selector the-model="string"/>
     * ```
     * @param {string} theModel Assignable angular expression to data-bind selected event
     */
    angular.module('oplus.udp').component('udpPageEventSelector', {
        templateUrl: 'app/modules/udp/widgets/page-event-selector.html',
        bindings: {
            theModel: '='
        },
        controller: ['widgetFactory', 'messageService', PageEventSelectorCtrl]
    });

    /**
     * @param widgetFactory {widgetFactory}
     */
    function PageEventSelectorCtrl(widgetFactory) {
        var ctrl = this;
        ctrl.pageEvents = [];
        ctrl.$onInit = function () {
            findPageEvents();
        };

        function findPageEvents() {
            var widgets = widgetFactory.findEventWidgets();
            var uwTypes = _.map(widgets, function (w) {
                return '.uwtype-' + w.type;
            });
            // var map = {};
            // widgets.forEach(function (w) {
            //     map[w.type] = w.eventProperty;
            // });
            $('#pd-canvas-zone').find(uwTypes.join(',')).each(function () {
                var $elem = $(this);
                var eventProp = _.find(widgets, {type: $elem.attr('uw-type')}).eventProperty;
                var uwProps = JSON.parse($elem.attr('uw-props') || '{}');
                var eventName = _.get(uwProps, eventProp);
                // console.log($elem.attr('uw-type'), uwProps, eventProp, eventName);
                if (eventName) {
                    ctrl.pageEvents.push({name: eventName});
                }
            });
        }
    }
})();
